def format_receipt(items):
    lines = ["RECEIPT", "-" * 20]
    total = 0.0
    for name, qty, price in items:
        lines.append(f"{name[:10]:<10} {qty} x {price:.2f}")
        total += qty * price
    lines.append("-" * 20)
    lines.append(f"TOTAL {total:.2f}")
    return "\n".join(lines)

