def core_handler(request):
    return {"status": 200, "body": "hello " + request["user"], "headers": {}}

def add_header(handler):
    def wrapped(request):
        response = handler(request)
        response["headers"]["x-app"] = "mint"
        return response
    return wrapped

class PassThrough:
    def __init__(self, next_handler):
        self.next_handler = next_handler
    def handle(self, request):
        return self.next_handler(request)

def with_passthrough(request):
    chain = add_header(PassThrough(core_handler).handle)
    return chain(request)

def without_passthrough(request):
    chain = add_header(core_handler)
    return chain(request)

for user in ("ada", "grace"):
    req = {"user": user}
    b, a = with_passthrough(req), without_passthrough(req)
    print(b, "| identical:", b == a)
    assert b == a
print("pass-through removed; end-to-end responses identical")

