def parse_port_before(text):
    if text:
        if text.isdigit():
            n = int(text)
            if 1 <= n <= 65535:
                return ("ok", n)
            else:
                return ("error", "out of range")
        else:
            return ("error", "not a number")
    else:
        return ("error", "empty")

def parse_port_after(text):
    if not text:
        return ("error", "empty")
    if not text.isdigit():
        return ("error", "not a number")
    n = int(text)
    if not (1 <= n <= 65535):
        return ("error", "out of range")
    return ("ok", n)

for text in ("", "abc", "0", "70000", "8080", "12x", "-5"):
