        return ["pay", "cancel"]
    if status == "paid":
        return ["ship", "refund"]
    if status == "shipped":
        return ["track", "refund"]
    raise ValueError("unknown status: " + status)

class Status(Enum):
    NEW = "new"
    PAID = "paid"
    SHIPPED = "shipped"

def actions_after(status):
    if status is Status.NEW:
        return ["pay", "cancel"]
    if status is Status.PAID:
        return ["ship", "refund"]
    if status is Status.SHIPPED:
        return ["track", "refund"]
    raise ValueError("unknown status: " + repr(status))

for text in ("new", "paid", "shipped"):
    b = actions_before(text)
    a = actions_after(Status(text))
    print(text, "-> before:", b, "| after:", a, "| identical:", b == a)
    assert b == a
